// Employee meals: incremental writeoff during the day, BUKHARA test.
(function(){
 state.mealDishes=[];state.mealQty={};state.mealSummary=[];state.mealBusy=false;
 function actor(){return localStorage.getItem('stolovaya:employee-name')||sessionStorage.getItem('stolovaya:employee-name')||'Буфетчик'}
 const bh=homeScreen;homeScreen=function(){let h=bh();if(state.point!=='BUKHARA')return h;const disabled=state.home?.submitted||state.home?.dayClosed?'disabled':'';const meal=`<button type="button" id="employee-meal-open" ${disabled}><span>♨</span><div><b>Питание</b><small>Бесплатная еда сотрудников</small></div></button>`;if(h.includes('id="kitchen-supply-open"'))return h.replace(/(<button type="button" id="kitchen-supply-open"[\s\S]*?<\/button>)/,`$1${meal}`);return h.replace(/(<section class="home-actions">)/,`$1${meal}`)};
 async function loadMeal(){state.mealBusy=true;render();try{const [d,s]=await Promise.all([rpc('public_kitchen_supply_dishes',{p_token:state.token,p_point_code:state.point}),rpc('public_employee_meal_summary',{p_token:state.token,p_point_code:state.point,p_business_date:businessDate()})]);state.mealDishes=d||[];state.mealSummary=s||[]}catch(e){state.message=e.message||'Не удалось загрузить питание'}finally{state.mealBusy=false;render()}}
 function summary(id){return state.mealSummary.find(x=>x.dish_id===id)||{} }
 function availableDishes(){return(state.mealDishes||[]).map(d=>{const s=summary(d.dishId);return {...d,available:n(s.available_qty??d.availableQty??d.available??0),already:n(s.total_qty||0)}}).filter(d=>d.available>0||d.already>0).sort((a,b)=>clean(a.name).localeCompare(clean(b.name),'ru'))}
 function screen(){const rows=availableDishes();return `${header()}${back('Питание')}<section class="question-card"><h2>Бесплатная еда сотрудников</h2><p>Введите количество напротив нужных блюд и нажмите «Сохранить». Можно сохранять сколько угодно раз за день — новое количество добавится к уже учтённому.</p></section>${state.mealBusy?'<div class="notice">Загрузка…</div>':rows.length?`<div class="simple-cards meal-list">${rows.map(x=>`<article><div class="meal-name"><b>${esc(clean(x.name))}</b><small>Доступно: ${n(x.available)} · Уже учтено: <b>${n(x.already)}</b></small></div><div class="meal-qty"><input data-meal-qty="${x.dishId}" inputmode="decimal" placeholder="0" value="${esc(state.mealQty[x.dishId]||'')}"></div></article>`).join('')}</div>`:'<div class="notice">Нет доступных блюд.</div>'}<div class="sticky-action"><button id="employee-meal-save" class="primary" ${state.mealBusy?'disabled':''}>${state.mealBusy?'Сохраняем…':'Сохранить'}</button></div>${state.message?`<p class="toast">${esc(state.message)}</p>`:''}`}
 async function save(){if(state.mealBusy)return;const items=Object.entries(state.mealQty).map(([dishId,q])=>({dishId,qty:n(q)})).filter(x=>x.qty>0);if(!items.length){state.message='Введите количество хотя бы для одного блюда.';render();return}state.mealBusy=true;state.message='';render();try{for(const x of items)await rpc('public_add_employee_meal',{p_token:state.token,p_point_code:state.point,p_dish_id:x.dishId,p_quantity:x.qty,p_actor:actor(),p_business_date:businessDate()});state.mealQty={};await loadPoint();await loadMeal();state.message='Питание сохранено. Количество добавлено к уже учтённому.';render()}catch(e){state.message=e.message||'Не удалось сохранить';state.mealBusy=false;render()}}
 const br=render;render=function(){if(state.screen==='employee-meal'){app.innerHTML=screen();bind();return}br()};
 const bb=bind;bind=function(){bb();document.getElementById('employee-meal-open')?.addEventListener('click',()=>{state.screen='employee-meal';state.message='';render();loadMeal()});document.querySelectorAll('[data-meal-qty]').forEach(inp=>inp.oninput=e=>{const v=e.target.value.replace(',','.');if(v&&!/^\d*(\.\d{0,3})?$/.test(v))return;state.mealQty[inp.dataset.mealQty]=v});document.getElementById('employee-meal-save')?.addEventListener('click',save)};
 const st=document.createElement('style');st.textContent='.meal-list article{align-items:center}.meal-name{display:flex;flex-direction:column;gap:4px;min-width:0}.meal-name small{color:#68716b}.meal-qty input{width:82px;text-align:center;font-size:18px}.meal-list{padding-bottom:84px}';document.head.appendChild(st);
})();